/**
 * Decision 22's validation: the empirical sampler must agree with the exact value, within its own interval, on every rung
 * of rules that have one: tilted (importance-sampled) top rungs included. Three representative pairings here (the full
 * table of every exact pairing is regenerated by `pnpm --filter @workspace/v2-valuation grid-validate`).
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { gridType, grid4 } from "@workspace/v2-grid";
import { exactGridLadder } from "../src/exact-grid.ts";
import { sampleGridLadder } from "../src/sample-grid.ts";

const CASES: [string, string][] = [["opposite-nines", "top-half"], ["leapfrog", "zeros"]];

for (const [id, tb] of CASES) {
  test(`${id} + ${tb}: every converged sampled rung agrees with the exact sum within 3 standard errors`, { timeout: 300_000 }, () => {
    const f = gridType.families.find(x => x.id === id)!;
    const p = f.dealable(grid4)[0];
    const ex = exactGridLadder(gridType, f, p, grid4, tb);
    const s = sampleGridLadder(gridType, f, p, grid4, tb, "validate");
    const top = ex.lo.length - 1;
    assert.ok(s.convergedThrough >= top / 2, `converged through ${s.convergedThrough} of ${top}`);
    for (let k = 1; k <= s.convergedThrough; k++) {
      const d = Math.abs(s.rungs[k]!.bits - ex.lo[k]!);
      assert.ok(d <= 3 * s.rungs[k]!.error + 1e-9, `rung ${k}: sampled ${s.rungs[k]!.bits.toFixed(3)} ± ${s.rungs[k]!.error.toFixed(3)}, exact ${ex.lo[k]!.toFixed(3)}`);
    }
  });
}
